<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request } from '../../services/api'
const products=ref([]), cart=ref({}), keyword=ref(''), category=ref('全部'), shopper=ref('demo-01'), orders=ref([]), note=ref(''), loading=ref(true);const cats=['全部','饮品','乳品','食品','零食'];const filtered=computed(()=>products.value.filter(p=>(category.value==='全部'||p.category===category.value)&&(!keyword.value||p.name.includes(keyword.value))));const count=computed(()=>Object.values(cart.value).reduce((a,b)=>a+b,0));const total=computed(()=>products.value.reduce((a,p)=>a+(cart.value[p.id]||0)*p.price,0));
async function load(){try{products.value=await request('/api/products');orders.value=await request(`/api/orders?shopper=${shopper.value}`)}catch(e){note.value=e.message||'服务暂不可用'}finally{loading.value=false}}function add(p){if(!p.stock){note.value='该商品暂时缺货';return}cart.value={...cart.value,[p.id]:Math.min(p.stock,(cart.value[p.id]||0)+1)};uni.setStorageSync('selfshop-cart',cart.value)}function minus(p){cart.value={...cart.value,[p.id]:Math.max(0,(cart.value[p.id]||0)-1)};uni.setStorageSync('selfshop-cart',cart.value)}async function scan(){try{const result=await new Promise((resolve,reject)=>uni.scanCode({success:resolve,fail:reject}));const p=await request(`/api/products/barcode/${encodeURIComponent(result.result)}`);add(p);note.value=`已识别：${p.name}`}catch(e){note.value='扫码演示：可在开发者工具调用扫码，当前先使用商品卡片添加'}}async function checkout(){try{const items=Object.entries(cart.value).filter(([,q])=>q>0).map(([productId,quantity])=>({productId:Number(productId),quantity}));if(!items.length)throw Error('购物袋还是空的');const result=await request('/api/orders','POST',{shopper:shopper.value,items});orders.value=[result,...orders.value];cart.value={};uni.setStorageSync('selfshop-cart',cart.value);note.value=`结算成功，订单 #${result.id} 已创建（待支付演示）`;uni.showToast({title:'结算成功',icon:'success'})}catch(e){note.value=e.message||'结算失败'}}onLoad(()=>{cart.value=uni.getStorageSync('selfshop-cart')||{};load()})
</script>
<template>
<view class="page">
  <view class="nav"><view><text class="brand">拾光</text><text class="nav-sub">SMART STORE</text></view><view class="store-pill"><text class="dot">●</text> 门店自取</view></view>
  <view class="hero-card"><view><text class="eyebrow">SHOP SMART · LIVE LIGHT</text><text class="title">拿了就走，轻松结算</text><text class="subtitle">扫码识别 · 库存校验 · 自助下单</text><view class="hero-tags"><text>快捷购物</text><text>无需排队</text></view></view><view class="hero-icon">🛒</view></view>
  <view class="search-box"><text class="search-icon">⌕</text><input v-model="keyword" placeholder="搜索商品名称"/><button @click="scan">扫码</button></view>
  <view class="section-head"><view><text class="section-title">逛一逛</text><text class="section-desc">今天也要好好补给自己</text></view><text class="section-link">{{filtered.length}} 件商品</text></view>
  <scroll-view scroll-x class="cats"><text v-for="c in cats" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</text></scroll-view>
  <view v-if="loading" class="empty">正在加载商品...</view>
  <view v-else class="grid"><view v-for="p in filtered" :key="p.id" class="product"><view class="visual">{{p.icon}}<text v-if="p.badge" class="badge">{{p.badge}}</text><text v-if="p.stock<10" class="stock">仅剩 {{p.stock}}</text></view><text class="category">{{p.category}}</text><text class="name">{{p.name}}</text><view class="product-bottom"><view><text class="price">¥{{p.price}}</text><text class="price-tip">/ 件</text></view><view class="stepper" v-if="cart[p.id]"><button @click="minus(p)">−</button><text>{{cart[p.id]}}</text><button @click="add(p)">＋</button></view><button v-else class="add" @click="add(p)">加入</button></view></view></view>
  <view class="section-head orders-title"><view><text class="section-title">最近订单</text><text class="section-desc">自助结算记录</text></view><text class="section-link">{{orders.length}} 笔</text></view><view v-for="o in orders" :key="o.id" class="order"><view><text class="order-id">订单 #{{o.id}} <text>· ¥{{o.total}}</text></text><text class="order-detail">{{o.items.map(x=>x.name+'×'+x.quantity).join('、')}}</text></view><text class="status">{{o.status}}</text></view><view v-if="!orders.length" class="empty-panel">暂无订单，选点喜欢的带走吧</view>
  <view class="bottom"><view><text class="count">购物袋 {{count}} 件</text><text class="total">¥{{total}}</text></view><button @click="checkout" :disabled="!count">立即结算 <text>→</text></button></view><view v-if="note" class="toast">{{note}}</view>
</view>
</template>
