x;margin-right:10rpx;background:#fff;color:#8d97a5;border-radius:18rpx;font-size:21rpx}.cats text.active{background:#1677ff;color:#fff;font-weight:700;box-shadow:0 8rpx 18rpx #1677ff33}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14rpx}.product{overflow:hidden;background:#fff;border-radius:24rpx;padding-bottom:16rpx;box-shadow:0 8rpx 20rpx #22324a08}.visual{position:relative;height:220rpx;display:flex;align-items:center;justify-content:center;font-size:94rpx;background:linear-gradient(145deg,#e7f3ff,#cbe5f8)}.product:nth-child(3n+2) .visual{background:linear-gradient(145deg,#eaf8f3,#c8eadc)}.product:nth-child(3n) .visual{background:linear-gradient(145deg,#fff2de,#f8dcc0)}.badge{position:absolute;left:12rpx;top:12rpx;border-radius:10rpx;padding:5rpx 9rpx;background:#1677ff;color:#fff;font-size:16rpx}.stock{position:absolute;right:10rpx;bottom:10rpx;border-radius:10rpx;padding:5rpx 8rpx;background:#ffffffdc;color:#d66c42;font-size:16rpx}.category,.name{display:block;padding:0 16rpx}.category{color:#9aa5b2;font-size:18rpx;margin-top:13rpx}.name{font-size:25rpx;font-weight:800;margin-top:8rpx}.product-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:15rpx;padding:0 16rpx}.price{font-size:29rpx;color:#e05b3f;font-weight:800}.price-tip{font-size:17rpx;color:#a6adb6;margin-left:4rpx}.add{height:52rpx;line-height:52rpx;margin:0;background:#1677ff;color:#fff;border:0;font-size:19rpx;padding:0 17rpx}.stepper{display:flex;align-items:center;gap:7rpx}.stepper button{width:43rpx;height:43rpx;line-height:38rpx;padding:0;border:1rpx solid #dbe5f0;background:#fff;color:#176dc0;font-size:24rpx}.stepper button:last-child{background:#1677ff;border-color:#1677ff;color:#fff}.stepper text{min-width:18rpx;text-align:center;font-size:19rpx}.orders-title{margin-top:30rpx}.order{display:flex;align-items:center;justify-content:space-between;padding:20rpx;background:#fff;border-radius:20rpx;margin-bottom:10rpx}.order-id{display:block;font-weight:800;font-